; =====================
; CORES
; =====================
COR_TITULO          db 0, 0AH              ; verde-claro
COR_BOTAO           db 0, 0FH              ; branco
COR_SELEC           db 0, 0CH              ; vermelho-claro (op??o selecionada)
COR_CORACAO         db 0, 04H              ; vermelho
COR_RELOGIO         db 0, 0EH              ; amarelo

NAVE_PALETA         db 0, 09H, 0EH, 04H
JIPE_PALETA         db 0, 0CH, 09H, 01H, 04H
TERRENO_LONGE_PALETA db 0, 01H, 09H

; =====================
; ELEMENTOS B?SICOS DA INTERFACE
; =====================
LARG_TELA equ 320
LARGURA   equ 5                              ; largura do glifo (px)
ALTURA    equ 8                              ; altura do glifo (px)

ASCII_X   dw 0
ASCII_Y   dw 0

; =====================
; T?TULO
; =====================
LARGURA_TITULO   equ 5                       ; largura da c?lula (avan?o em X)
ALTURA_TITULO    equ 8                       ; altura da c?lula (avan?o em Y)
X_INICIAL_TITULO equ 22                      ; (320 - 55 * 5) / 2
Y_INICIAL_TITULO equ 10

; =====================
; ?NDICES DOS GLIFOS
; =====================
G_ESPACO     equ 0
G_CANTO_SE   equ 10                          ; canto superior esquerdo
G_CANTO_SD   equ 11                          ; canto superior direito
G_CANTO_IE   equ 12                          ; canto inferior esquerdo
G_CANTO_ID   equ 13                          ; canto inferior direito
G_HORIZ      equ 14                          ; linha horizontal
G_VERT       equ 15                          ; linha vertical
NUM_GLYPHS   equ 23

; =====================
; BOT?O MENU INICIAL
; =====================
TXT_JOGAR   db "Jogar", 0
TXT_SAIR    db "Sair", 0

BTN_JOGAR_Y equ 130                          ; Y do bot?o Jogar
BTN_SAIR_Y  equ 160                          ; Y do bot?o Sair
NUM_OPCOES  equ 2

BTN_X       dw 0
BTN_Y       dw 0
BTN_MEIO    dw 0                             ; c?lulas entre os cantos (letras + 2)
BTN_TXT     dw 0                             ; endere?o do texto do bot?o
OPCAO_SEL   db 0

; =====================
; CORA??O
; =====================
LARGURA_CORACAO equ 18
ALTURA_CORACAO  equ 12

; =====================
; REL?GIO
; =====================
LARGURA_RELOGIO equ 7
ALTURA_RELOGIO  equ 8

; =====================
; NAVES
; =====================
LARGURA_NAVE equ 14
ALTURA_NAVE  equ 14

; =====================
; JIPE
; =====================
LARGURA_JIPE equ 20
ALTURA_JIPE  equ 10

; Caractere ASCII de cada glifo, na posi??o do seu ?ndice
; (?ndices 10 a 15 s?o de moldura e n?o t?m ASCII: ficam com 0)
FONTE_CHARS db ' ', 27H, '`', '(', ')', '/', '\', '_', '|', ','
            db 0, 0, 0, 0, 0, 0
            db 'J', 'O', 'G', 'A', 'R', 'S', 'I'

; 8 bytes por glifo (uma linha por byte)
; bit 4 = coluna da esquerda, bit 0 = coluna da direita
FONTE_GLYPHS label byte
    db 00H, 00H, 00H, 00H, 00H, 00H, 00H, 00H   ; 0  espa?o
    db 04H, 04H, 00H, 00H, 00H, 00H, 00H, 00H   ; 1  '
    db 08H, 04H, 00H, 00H, 00H, 00H, 00H, 00H   ; 2  `
    db 02H, 04H, 08H, 08H, 08H, 08H, 04H, 02H   ; 3  (
    db 08H, 04H, 02H, 02H, 02H, 02H, 04H, 08H   ; 4  )
    db 01H, 02H, 02H, 04H, 04H, 08H, 08H, 10H   ; 5  /
    db 10H, 08H, 08H, 04H, 04H, 02H, 02H, 01H   ; 6  \
    db 00H, 00H, 00H, 00H, 00H, 00H, 00H, 1FH   ; 7  _
    db 04H, 04H, 04H, 04H, 04H, 04H, 04H, 04H   ; 8  |
    db 00H, 00H, 00H, 00H, 00H, 04H, 04H, 08H   ; 9  ,
    db 00H, 00H, 00H, 07H, 04H, 04H, 04H, 04H   ; 10 canto sup. esq.
    db 00H, 00H, 00H, 1CH, 04H, 04H, 04H, 04H   ; 11 canto sup. dir.
    db 04H, 04H, 04H, 07H, 00H, 00H, 00H, 00H   ; 12 canto inf. esq.
    db 04H, 04H, 04H, 1CH, 00H, 00H, 00H, 00H   ; 13 canto inf. dir.
    db 00H, 00H, 00H, 1FH, 00H, 00H, 00H, 00H   ; 14 horizontal
    db 04H, 04H, 04H, 04H, 04H, 04H, 04H, 04H   ; 15 vertical

FONTE_LETRAS label byte
    db 02H, 02H, 02H, 02H, 12H, 12H, 0CH, 00H   ; 16 J
    db 0CH, 12H, 12H, 12H, 12H, 12H, 0CH, 00H   ; 17 O
    db 0CH, 12H, 10H, 16H, 12H, 12H, 0CH, 00H   ; 18 G
    db 0CH, 12H, 12H, 1EH, 12H, 12H, 12H, 00H   ; 19 A
    db 1CH, 12H, 12H, 1CH, 14H, 12H, 12H, 00H   ; 20 R
    db 0EH, 10H, 10H, 0CH, 02H, 02H, 1CH, 00H   ; 21 S
    db 0EH, 04H, 04H, 04H, 04H, 04H, 0EH, 00H   ; 22 I

; =====================================================================
; C?DIGO
; =====================================================================
.code

; ---------------------------------------------------------------------
; MODO_VIDEO: configura o modo gr?fico 13H (320x200, 256 cores)
; ---------------------------------------------------------------------
MODO_VIDEO proc
    mov AX, 0013H                            ; modo 13H: 320x200, 256 cores
    int 10H
    ret
MODO_VIDEO endp

; ---------------------------------------------------------------------
; ASCII_PARA_INDICE: converte um caractere ASCII no ?ndice do glifo
;   (min?scula vira mai?scula; desconhecido vira espa?o)
; Entrada: AL = caractere ASCII
; Sa?da:   AL = ?ndice do glifo (BX e CX preservados)
; ---------------------------------------------------------------------
ASCII_PARA_INDICE proc
    push BX
    push CX

    cmp AL, 'a'                              ; min?scula vira mai?scula
    jb  procura
    cmp AL, 'z'
    ja  procura
    sub AL, 20H

procura:
    mov BX, offset FONTE_CHARS
    mov CX, NUM_GLYPHS

procura_loop:
    cmp AL, [BX]
    je  achou
    inc BX
    loop procura_loop

    mov AL, G_ESPACO                         ; n?o existe na fonte: espa?o
    jmp fim_conversao

achou:
    sub BX, offset FONTE_CHARS               ; BX = ?ndice
    mov AL, BL

fim_conversao:
    pop CX
    pop BX
    ret
ASCII_PARA_INDICE endp

; ---------------------------------------------------------------------
; DESENHA_CARACTERE: desenha um glifo da fonte bitmap na VRAM
; Entrada: AL = ?ndice do glifo na tabela
;          ASCII_X, ASCII_Y = posi??o do canto superior esquerdo
;          COR_ATUAL = cor; ES = 0A000H
; ---------------------------------------------------------------------
DESENHA_CARACTERE proc
    push AX
    push BX
    push CX
    push DX
    push SI
    push DI
    push BP

    xor AH, AH                               ; AX = ?ndice do glifo
    shl AX, 3                                ; AX = ?ndice * 8
    mov SI, offset FONTE_GLYPHS
    add SI, AX                               ; SI = glifo

    mov AX, ASCII_Y
    mov BX, LARG_TELA
    mul BX                                   ; AX = Y * 320
    add AX, ASCII_X
    mov BH, [DI + 1]                         ; BH = cor (entrada 1 da paleta em DI)
    mov DI, AX                               ; DI = Y * 320 + X

    mov AL, BH                               ; AL = cor
    mov BP, ALTURA                           ; contador de linhas
proxima_linha:
    mov BL, [SI]                             ; BL = linha do glifo
    inc SI
    mov CX, LARGURA                          ; 5 colunas

proximo_pixel:
    test BL, 10H                             ; bit 4 = pixel mais ? esquerda
    jz   pixel_vazio
    stosb                                    ; ES:[DI] = AL, DI = DI + 1
    jmp  proximo_bit

pixel_vazio:
    inc DI                                   ; pula o pixel sem pintar

proximo_bit:
    shl BL, 1
    loop proximo_pixel

    add DI, LARG_TELA - LARGURA              ; desce uma linha, mesma coluna inicial
    dec BP
    jnz proxima_linha

    pop BP
    pop DI
    pop SI
    pop DX
    pop CX
    pop BX
    pop AX
    ret
DESENHA_CARACTERE endp

; ---------------------------------------------------------------------
; DESENHA_LINHA_BOX: desenha uma linha de c?lulas (esquerda, meio
;   repetido e direita), avan?ando ASCII_X
; Entrada: AL = ?ndice do glifo da esquerda
;          AH = ?ndice do glifo do meio
;          DL = ?ndice do glifo da direita
;          CX = quantidade de c?lulas do meio
;          ASCII_X, ASCII_Y = posi??o inicial; ES = 0A000H
; ---------------------------------------------------------------------
DESENHA_LINHA_BOX proc
    push AX
    push CX

    call DESENHA_CARACTERE                   ; esquerda
    add ASCII_X, LARGURA

    mov AL, AH                               ; AL = glifo do meio

meio_loop:
    call DESENHA_CARACTERE                   ; preserva AX, CX e DX
    add ASCII_X, LARGURA
    loop meio_loop

    mov AL, DL                               ; AL = direita
    call DESENHA_CARACTERE
    add ASCII_X, LARGURA

    pop CX
    pop AX
    ret
DESENHA_LINHA_BOX endp

; ---------------------------------------------------------------------
; DESENHA_BOTAO: desenha um bot?o de 3 c?lulas de altura, com moldura
;   e texto, centralizado horizontalmente na tela
; Entrada: SI = endere?o do texto terminado em 0
;          DX = Y do canto superior esquerdo do bot?o
;          COR_ATUAL; ES = 0A000H
; ---------------------------------------------------------------------
DESENHA_BOTAO proc
    push AX
    push BX
    push CX
    push DX
    push SI

    mov BTN_TXT, SI                          ; guarda o texto
    mov BTN_Y, DX                            ; guarda o Y

    xor CX, CX                               ; CX = quantidade de letras
    mov BX, SI

conta_letras:
    cmp byte ptr [BX], 0
    je  fim_conta
    inc BX
    inc CX
    jmp conta_letras

fim_conta:
    mov AX, CX
    add AX, 4                                ; c?lulas totais = letras + 4
    mov BX, LARGURA
    mul BX                                   ; AX = largura do bot?o em pixels
    mov BX, AX
    mov AX, LARG_TELA
    sub AX, BX
    shr AX, 1                                ; AX = (320 - largura) / 2
    mov BTN_X, AX

    add CX, 2                                ; c?lulas entre os cantos
    mov BTN_MEIO, CX

    ; linha de cima
    mov AX, BTN_X
    mov ASCII_X, AX
    mov AX, BTN_Y
    mov ASCII_Y, AX
    mov AL, G_CANTO_SE
    mov AH, G_HORIZ
    mov DL, G_CANTO_SD
    mov CX, BTN_MEIO
    call DESENHA_LINHA_BOX

    ; linha do meio (bordas laterais)
    mov AX, BTN_X
    mov ASCII_X, AX
    add ASCII_Y, ALTURA
    mov AL, G_VERT
    mov AH, G_ESPACO
    mov DL, G_VERT
    mov CX, BTN_MEIO
    call DESENHA_LINHA_BOX

    ; linha de baixo
    mov AX, BTN_X
    mov ASCII_X, AX
    add ASCII_Y, ALTURA
    mov AL, G_CANTO_IE
    mov AH, G_HORIZ
    mov DL, G_CANTO_ID
    mov CX, BTN_MEIO
    call DESENHA_LINHA_BOX

    ; texto na c?lula 2 da linha do meio
    mov AX, BTN_X
    add AX, 2 * LARGURA
    mov ASCII_X, AX
    mov AX, BTN_Y
    add AX, ALTURA
    mov ASCII_Y, AX
    mov CX, LARGURA
    mov DX, ALTURA
    mov SI, BTN_TXT
    call DESENHA_ASCII

    pop SI
    pop DX
    pop CX
    pop BX
    pop AX
    ret
DESENHA_BOTAO endp

; ---------------------------------------------------------------------
; DESENHA_MENU: desenha os bot?es Jogar e Sair; o bot?o da op??o
;   selecionada usa COR_SELEC e os demais COR_BOTAO
; Entrada: OPCAO_SEL = op??o selecionada (0 = Jogar, 1 = Sair)
;          ES = 0A000H
; ---------------------------------------------------------------------
DESENHA_MENU proc
    push DX
    push SI

    mov DI, offset COR_BOTAO                 ; paleta: nao selecionado
    cmp OPCAO_SEL, 0
    jne menu_jogar_cor
    mov DI, offset COR_SELEC                 ; Jogar esta selecionado
menu_jogar_cor:
    mov SI, offset TXT_JOGAR
    mov DX, BTN_JOGAR_Y
    call DESENHA_BOTAO

    mov DI, offset COR_BOTAO
    cmp OPCAO_SEL, 1
    jne menu_sair_cor
    mov DI, offset COR_SELEC                 ; Sair esta selecionado

menu_sair_cor:
    mov SI, offset TXT_SAIR
    mov DX, BTN_SAIR_Y
    call DESENHA_BOTAO

    pop SI
    pop DX
    ret
DESENHA_MENU endp

; ---------------------------------------------------------------------
; MENU: desenha o menu e l? o teclado; seta para cima e para baixo
;   trocam a op??o, Enter confirma e retorna
; Entrada: ES = 0A000H
; Sa?da:   OPCAO_SEL = op??o escolhida (0 = Jogar, 1 = Sair)
; ---------------------------------------------------------------------
MENU proc
    push AX

menu_desenha:
    call DESENHA_MENU

menu_tecla:
    mov AH, 00H
    int 16H                                  ; AH = scan code, AL = ASCII

    cmp AH, 48H                              ; seta para cima
    je  menu_cima
    cmp AH, 50H                              ; seta para baixo
    je  menu_baixo
    cmp AL, 13                               ; Enter
    je  menu_enter
    jmp menu_tecla                           ; outra tecla: ignora

menu_cima:
    cmp OPCAO_SEL, 0                         ; j? na primeira op??o
    je  menu_tecla
    dec OPCAO_SEL
    jmp menu_desenha

menu_baixo:
    cmp OPCAO_SEL, NUM_OPCOES - 1            ; j? na ?ltima op??o
    jae menu_tecla
    inc OPCAO_SEL
    jmp menu_desenha

menu_enter:
    pop AX
    ret
MENU endp

; ---------------------------------------------------------------------
; DESENHA_ASCII: desenha uma arte ASCII de v?rias linhas (CR ignorado,
;   LF volta ao X inicial e desce uma linha, 0 encerra)
; Entrada: DS:SI = endere?o da string terminada em 0
;          ASCII_X, ASCII_Y = posi??o inicial; COR_ATUAL; ES = 0A000H
;          CX = largura da c?lula (avan?o em X por caractere)
;          DX = altura da c?lula (avan?o em Y por linha)
; ---------------------------------------------------------------------
DESENHA_ASCII proc
    push AX
    push BX
    push SI

    mov BX, ASCII_X                          ; BX = X inicial (para o retorno do LF)

exibir:
    lodsb                                    ; AL = DS:[SI], SI = SI + 1
    cmp AL, 0
    je  fim
    cmp AL, 13                               ; CR: ignora
    je  exibir
    cmp AL, 10                               ; LF: pr?xima linha
    je  nova_linha

    call ASCII_PARA_INDICE                   ; AL = ?ndice do glifo (preserva BX, CX)
    call DESENHA_CARACTERE                   ; preserva todos os registradores
    add ASCII_X, CX                          ; avan?a uma c?lula em X
    jmp exibir

nova_linha:
    mov ASCII_X, BX                          ; X volta ao inicial
    add ASCII_Y, DX                          ; desce uma c?lula em Y
    jmp exibir

fim:
    pop SI
    pop BX
    pop AX
    ret
DESENHA_ASCII endp

; ---------------------------------------------------------------------
; DESENHA_ASCII_PALETA: desenha um sprite colorido; o valor de cada
;   pixel ? traduzido para uma cor por uma paleta (0 = transparente)
; Entrada: SI = endere?o do sprite (uma linha ap?s a outra)
;          BX = endere?o da paleta (tabela de cores indexada pelo
;               valor do pixel)
;          CX = largura do sprite (colunas)
;          DX = altura do sprite (linhas)
;          ASCII_X, ASCII_Y = canto superior esquerdo na tela
;          ES = 0A000H; DF = 0 (CLD)
; ---------------------------------------------------------------------
DESENHA_ASCII_PALETA proc
    push AX
    push BX
    push CX
    push DX
    push SI
    push DI
    push BP

    mov BP, DX
    mov AX, ASCII_Y
    mov DX, LARG_TELA
    mul DX
    add AX, ASCII_X
    mov DI, AX
    mov DX, CX

paleta_linha:
    mov CX, DX

paleta_pixel:
    lodsb
    sub AL, '0'
    cmp AL, 0
    je  paleta_vazio
    xlat
    stosb
    jmp paleta_proximo

paleta_vazio:
    inc DI

paleta_proximo:
    loop paleta_pixel

    add SI, 2                                ; pula o CR e o LF do fim da linha
    add DI, LARG_TELA
    sub DI, DX
    dec BP
    jnz paleta_linha

    pop BP
    pop DI
    pop SI
    pop DX
    pop CX
    pop BX
    pop AX
    ret
DESENHA_ASCII_PALETA endp

; ---------------------------------------------------------------------
; MENU_INICIAL: desenha o t?tulo do jogo e o menu, e espera o
;   usu?rio escolher uma op??o
; Entrada: ES = 0A000H
; Sa?da:   OPCAO_SEL = op??o escolhida (0 = Jogar, 1 = Sair)
; ---------------------------------------------------------------------
MENU_INICIAL proc
    push AX
    push CX
    push DX
    push SI

    mov DI, offset COR_TITULO            
    mov ASCII_X, X_INICIAL_TITULO            ; posi??o inicial do t?tulo
    mov ASCII_Y, Y_INICIAL_TITULO
    mov CX, LARGURA_TITULO                   ; avan?o em X
    mov DX, ALTURA_TITULO                    ; avan?o em Y
    mov SI, offset TITULO_JOGO
    call DESENHA_ASCII

    mov ASCII_X, 110                         ; X do canto superior esquerdo
    mov ASCII_Y, 100                         ; Y do canto superior esquerdo
    mov SI, offset JIPE_SPRITE
    mov BX, offset JIPE_PALETA
    mov CX, LARGURA_JIPE
    mov DX, ALTURA_JIPE
    call DESENHA_ASCII_PALETA

    mov ASCII_X, 140
    mov SI, offset NAVE1_SPRITE
    mov BX, offset NAVE_PALETA
    mov CX, LARGURA_NAVE
    mov DX, ALTURA_NAVE
    call DESENHA_ASCII_PALETA

    mov ASCII_X, 170
    mov SI, offset NAVE2_SPRITE
    call DESENHA_ASCII_PALETA

    mov ASCII_X, 200
    mov SI, offset NAVE3_SPRITE
    call DESENHA_ASCII_PALETA

    call MENU                                ; desenha os bot?es e espera Enter

    pop SI
    pop DX
    pop CX
    pop AX
    ret
MENU_INICIAL endp

; ---------------------------------------------------------------------
; INICIA_JOGO: inicializa os elementos do jogo (cora??o e rel?gio)
; ---------------------------------------------------------------------
INICIA_JOGO proc
    mov ASCII_X, 10
    mov ASCII_Y, 10
    mov SI, offset CORACAO_SPRITE
    mov BX, offset COR_CORACAO
    mov CX, LARGURA_CORACAO
    mov DX, ALTURA_CORACAO
    call DESENHA_ASCII_PALETA

    mov ASCII_X, 280
    mov ASCII_Y, 10
    mov SI, offset RELOGIO_SPRITE
    mov BX, offset COR_RELOGIO
    mov CX, LARGURA_RELOGIO
    mov DX, ALTURA_RELOGIO
    call DESENHA_ASCII_PALETA
    ret
INICIA_JOGO endp

; =====================================================================
; PONTO DE ENTRADA
; =====================================================================
start:
    mov AX, @data
    mov DS, AX

    mov AX, 0A000H
    mov ES, AX                               ; ES = segmento da VRAM

    cld                                      ; SI/DI incrementam

    call MODO_VIDEO

menu:
    call MENU_INICIAL                        ; t?tulo + menu: define OPCAO_SEL
    cmp OPCAO_SEL, 0
    jne fim_programa                         ; 1 = Sair
    call INICIA_JOGO                         ; 0 = Jogar
    jmp menu

fim_programa:
    mov AX, 0003H
    int 10H                                  ; volta ao modo texto
    mov AX, 4C00H
    int 21H                                  ; encerra

end start